mapper.select:
SELECT id, doc_id, kb_id, tenant_id, chunk_index, content, content_hash,
       metadata, token_count, is_active, created_at
FROM kb_chunk
WHERE doc_id   = #{docId}
  AND is_active = #{isActive}
ORDER BY chunk_index ASC

SELECT COUNT(*) FROM kb_chunk
WHERE kb_id    = #{kbId}
  AND is_active = #{isActive}
